<?php $this->layout('default'); use Moves\Services\HelpdeskNotifier as N; use Moves\Support\CmsView as V; $rows = N::inbox((int) $admin['id'], 'staff', 60); ?>
<div class="cms-actions"><?= V::actionButton('notifications-read', 'Marcar todas como lidas') ?></div><div class="cms-card"><?php if ($rows === []): ?><?= V::empty('Nenhuma notificação.') ?><?php endif; foreach ($rows as $n): ?><p><?= $n['read_at'] ? '' : V::badge('info', 'Nova') . ' ' ?><a href="<?= V::e($n['link']) ?>"><?= V::e($n['title']) ?></a> <small><?= V::date($n['created_at']) ?></small></p><?php endforeach; ?></div>
